import 'package:flutter/material.dart';
class DetailPage extends StatelessWidget { const DetailPage({super.key, required this.data}); final Map<String,String> data; @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Detail')), body: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(data['judul'] ?? 'Detail', style: const TextStyle(fontSize:24,fontWeight:FontWeight.bold)), const SizedBox(height:12), Text(data['isi'] ?? ''), const Spacer(), FilledButton(onPressed: ()=>Navigator.pop(context,'Informasi telah dibaca.'), child: const Text('Selesai'))]))); }
